import openpyxl
wb = openpyxl.load_workbook("Cost Estimates/DSR_Ph3_Engineers_Estimate.xlsx", data_only=True)

for sheet in ['Cover','Estimate','Summary']:
    ws = wb[sheet]
    print("\n========== SHEET:", sheet, "==========")
    for row in ws.iter_rows():
        vals = []
        for c in row:
            v = c.value
            if v is None:
                vals.append("")
            else:
                vals.append(str(v))
        # only print rows that have something
        if any(x!="" for x in vals):
            print(f"R{row[0].row}: " + " | ".join(vals))
EOF

